INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M31-CI001', 'HDSAT-RW-M31-CI001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Hip-hop (also known as rap music or simply rap) is a genre of popular music that emerged in the early 1970s alongside an associated subculture in New York City. The musical style is a synthesis of a wide range of techniques, but rapping is frequent enough that it has become a defining characteristic. Other key markers of the genre are the disc jockey (DJ), turntablism, scratching, beatboxing, and instrumental tracks. The hip-hop genre and culture emerged from block parties in the Bronx, with influences from African-American, Afro-Caribbean, and Latino communities. DJs began expanding the instrumental breaks of popular records when they noticed how excited it would make the crowds. The extended breaks provided a platform for break dancers and rappers. These breakbeats enabled the subsequent evolution of the hip-hop style. Many of the records used were disco due to its popularity at the time. This disco-inflected music was originally known as disco rap and later described as "old-school hip-hop". In the mid-1980s, hip-hop began to diversify as electro music started to inform the genre''s new school. The period between the mid-1980s and mid-1990s became known as hip-hop''s "golden age", as the genre earned widespread critical acclaim and generated massive sales. Across the United States, several regional scenes emerged, most notably on the East and West Coasts, as well as in the South, which included the Houston, Atlanta and Memphis rap scenes.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Hip-hop has no connection to DJ techniques."}, {"id": "B", "text": "Hip-hop remained confined to a single neighborhood."}, {"id": "C", "text": "Hip-hop began in the 1990s as a form of classical music."}, {"id": "D", "text": "Hip-hop emerged from Bronx block parties in the 1970s, with rapping and DJ techniques as defining features, and diversified into regional scenes."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Hip-hop", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Hip-hop', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M31-CI001', 'D', ARRAY['D']::TEXT[], 'The passage describes hip-hop''s origins, musical elements, and stylistic evolution.', '{"C": "The text dates its emergence to the early 1970s in New York City.", "A": "The text lists the DJ, turntablism, scratching, and beatboxing as key markers.", "B": "The text describes East Coast, West Coast, and Southern scenes."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M31-INF001', 'HDSAT-RW-M31-INF001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Hip-hop (also known as rap music or simply rap) is a genre of popular music that emerged in the early 1970s alongside an associated subculture in New York City. The musical style is a synthesis of a wide range of techniques, but rapping is frequent enough that it has become a defining characteristic. Other key markers of the genre are the disc jockey (DJ), turntablism, scratching, beatboxing, and instrumental tracks. The hip-hop genre and culture emerged from block parties in the Bronx, with influences from African-American, Afro-Caribbean, and Latino communities. DJs began expanding the instrumental breaks of popular records when they noticed how excited it would make the crowds. The extended breaks provided a platform for break dancers and rappers. These breakbeats enabled the subsequent evolution of the hip-hop style. Many of the records used were disco due to its popularity at the time. This disco-inflected music was originally known as disco rap and later described as "old-school hip-hop". In the mid-1980s, hip-hop began to diversify as electro music started to inform the genre''s new school. The period between the mid-1980s and mid-1990s became known as hip-hop''s "golden age", as the genre earned widespread critical acclaim and generated massive sales. Across the United States, several regional scenes emerged, most notably on the East and West Coasts, as well as in the South, which included the Houston, Atlanta and Memphis rap scenes.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M31-INF001', 'A', ARRAY['A']::TEXT[], 'The passage states that breakbeats enabled the later evolution of the hip-hop style.', '{"B": "The text says the extended breaks gave a platform to dancers and rappers and enabled the style''s evolution.", "C": "The breaks excited crowds rather than ending events.", "D": "The breaks provided a platform for rappers."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M31-TS001', 'HDSAT-RW-M31-TS001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Hip-hop (also known as rap music or simply rap) is a genre of popular music that emerged in the early 1970s alongside an associated subculture in New York City. The musical style is a synthesis of a wide range of techniques, but rapping is frequent enough that it has become a defining characteristic. Other key markers of the genre are the disc jockey (DJ), turntablism, scratching, beatboxing, and instrumental tracks. The hip-hop genre and culture emerged from block parties in the Bronx, with influences from African-American, Afro-Caribbean, and Latino communities. DJs began expanding the instrumental breaks of popular records when they noticed how excited it would make the crowds. The extended breaks provided a platform for break dancers and rappers. These breakbeats enabled the subsequent evolution of the hip-hop style. Many of the records used were disco due to its popularity at the time. This disco-inflected music was originally known as disco rap and later described as "old-school hip-hop". In the mid-1980s, hip-hop began to diversify as electro music started to inform the genre''s new school. The period between the mid-1980s and mid-1990s became known as hip-hop''s "golden age", as the genre earned widespread critical acclaim and generated massive sales. Across the United States, several regional scenes emerged, most notably on the East and West Coasts, as well as in the South, which included the Houston, Atlanta and Memphis rap scenes.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It profiles a single rapper''s career."}, {"id": "B", "text": "It describes hip-hop''s origins and elements, then traces its diversification and regional scenes."}, {"id": "C", "text": "It argues that hip-hop began in the 1980s."}, {"id": "D", "text": "It compares hip-hop with opera."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Hip-hop", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Hip-hop', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
