INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M31-CE001', 'HDSAT-RW-M31-CE001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Hip-hop (also known as rap music or simply rap) is a genre of popular music that emerged in the early 1970s alongside an associated subculture in New York City. The musical style is a synthesis of a wide range of techniques, but rapping is frequent enough that it has become a defining characteristic. Other key markers of the genre are the disc jockey (DJ), turntablism, scratching, beatboxing, and instrumental tracks. The hip-hop genre and culture emerged from block parties in the Bronx, with influences from African-American, Afro-Caribbean, and Latino communities. DJs began expanding the instrumental breaks of popular records when they noticed how excited it would make the crowds. The extended breaks provided a platform for break dancers and rappers. These breakbeats enabled the subsequent evolution of the hip-hop style. Many of the records used were disco due to its popularity at the time. This disco-inflected music was originally known as disco rap and later described as "old-school hip-hop". In the mid-1980s, hip-hop began to diversify as electro music started to inform the genre''s new school. The period between the mid-1980s and mid-1990s became known as hip-hop''s "golden age", as the genre earned widespread critical acclaim and generated massive sales. Across the United States, several regional scenes emerged, most notably on the East and West Coasts, as well as in the South, which included the Houston, Atlanta and Memphis rap scenes.', 'Which quotation from the text most directly supports the claim that hip-hop began at Bronx block parties?', '[{"id": "A", "text": "The period between the mid-1980s and mid-1990s became known as hip-hop''s \"golden age\"."}, {"id": "B", "text": "The hip-hop genre and culture emerged from block parties in the Bronx, with influences from African-American, Afro-Caribbean, and Latino communities."}, {"id": "C", "text": "Hip-hop is a genre of popular music that emerged in the early 1970s alongside an associated subculture in New York City."}, {"id": "D", "text": "The musical style is a synthesis of a wide range of techniques, but rapping is frequent enough that it has become a defining characteristic."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Hip-hop", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Hip-hop', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M31-CE001', 'B', ARRAY['B']::TEXT[], 'The correct quotation names Bronx block parties and the communities that shaped the genre.', '{"C": "This sentence gives the genre''s time and city.", "D": "This sentence describes its techniques.", "A": "This sentence names the golden age."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M31-CI002', 'HDSAT-RW-M31-CI002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Opera is a form of Western theatre in which music is a fundamental component and dramatic roles are taken by singers. Such a "work" (the literal translation of the Italian word "opera") is typically a collaboration between a composer and a librettist and incorporates a number of the performing arts, such as acting, scenery, costume, and sometimes dance or ballet. The performance is typically given in an opera house, accompanied by an orchestra or smaller musical ensemble, which since the early 19th century has been led by a conductor. Although musical theatre is closely related to opera, the two are considered to be distinct from one another. Opera is a key part of Western classical music, particularly classical music made in Italy. Originally understood as an entirely sung piece, in contrast to a play with songs, opera has come to include numerous genres, including some that include spoken dialogue such as Singspiel and Opéra comique. In traditional number opera, singers employ two styles of singing: recitative, a speech-inflected style, and self-contained arias. The 19th century saw the rise of the continuous music drama.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Opera is a spoken play with no music."}, {"id": "B", "text": "Opera is a Western theatrical form in which music is fundamental and singers perform dramatic roles, often combining several arts."}, {"id": "C", "text": "Opera is unrelated to Western classical music."}, {"id": "D", "text": "Opera involves only a solo singer and no orchestra."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Opera", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Opera', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M31-CI002', 'B', ARRAY['B']::TEXT[], 'The passage defines opera, describes its collaborative elements, and traces its genres and history.', '{"A": "The text says music is a fundamental component and roles are taken by singers.", "D": "The text says performance is accompanied by an orchestra or ensemble.", "C": "The text calls opera a key part of Western classical music."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M31-INF002', 'HDSAT-RW-M31-INF002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Opera is a form of Western theatre in which music is a fundamental component and dramatic roles are taken by singers. Such a "work" (the literal translation of the Italian word "opera") is typically a collaboration between a composer and a librettist and incorporates a number of the performing arts, such as acting, scenery, costume, and sometimes dance or ballet. The performance is typically given in an opera house, accompanied by an orchestra or smaller musical ensemble, which since the early 19th century has been led by a conductor. Although musical theatre is closely related to opera, the two are considered to be distinct from one another. Opera is a key part of Western classical music, particularly classical music made in Italy. Originally understood as an entirely sung piece, in contrast to a play with songs, opera has come to include numerous genres, including some that include spoken dialogue such as Singspiel and Opéra comique. In traditional number opera, singers employ two styles of singing: recitative, a speech-inflected style, and self-contained arias. The 19th century saw the rise of the continuous music drama.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M31-INF002', 'A', ARRAY['A']::TEXT[], 'The shift from entirely sung works to genres with spoken dialogue broadened the category.', '{"C": "The text says opera has come to include numerous genres, some with spoken dialogue.", "B": "Singing remains central to opera.", "D": "The text describes collaboration between composer and librettist."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M31-TS002', 'HDSAT-RW-M31-TS002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Opera is a form of Western theatre in which music is a fundamental component and dramatic roles are taken by singers. Such a "work" (the literal translation of the Italian word "opera") is typically a collaboration between a composer and a librettist and incorporates a number of the performing arts, such as acting, scenery, costume, and sometimes dance or ballet. The performance is typically given in an opera house, accompanied by an orchestra or smaller musical ensemble, which since the early 19th century has been led by a conductor. Although musical theatre is closely related to opera, the two are considered to be distinct from one another. Opera is a key part of Western classical music, particularly classical music made in Italy. Originally understood as an entirely sung piece, in contrast to a play with songs, opera has come to include numerous genres, including some that include spoken dialogue such as Singspiel and Opéra comique. In traditional number opera, singers employ two styles of singing: recitative, a speech-inflected style, and self-contained arias. The 19th century saw the rise of the continuous music drama.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It defines opera and its collaborators, distinguishes it from musical theatre, and describes its genres and singing styles."}, {"id": "B", "text": "It profiles a single composer."}, {"id": "C", "text": "It argues that opera has disappeared."}, {"id": "D", "text": "It compares Italian and German opera in detail."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Opera", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Opera', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
