INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M31-CE002', 'HDSAT-RW-M31-CE002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Opera is a form of Western theatre in which music is a fundamental component and dramatic roles are taken by singers. Such a "work" (the literal translation of the Italian word "opera") is typically a collaboration between a composer and a librettist and incorporates a number of the performing arts, such as acting, scenery, costume, and sometimes dance or ballet. The performance is typically given in an opera house, accompanied by an orchestra or smaller musical ensemble, which since the early 19th century has been led by a conductor. Although musical theatre is closely related to opera, the two are considered to be distinct from one another. Opera is a key part of Western classical music, particularly classical music made in Italy. Originally understood as an entirely sung piece, in contrast to a play with songs, opera has come to include numerous genres, including some that include spoken dialogue such as Singspiel and Opéra comique. In traditional number opera, singers employ two styles of singing: recitative, a speech-inflected style, and self-contained arias. The 19th century saw the rise of the continuous music drama.', 'Which quotation from the text most directly supports the claim that opera combines several performing arts?', '[{"id": "A", "text": "Although musical theatre is closely related to opera, the two are considered to be distinct from one another."}, {"id": "B", "text": "The performance is typically given in an opera house, accompanied by an orchestra or smaller musical ensemble."}, {"id": "C", "text": "Opera is a form of Western theatre in which music is a fundamental component and dramatic roles are taken by singers."}, {"id": "D", "text": "Such a \"work\" (the literal translation of the Italian word \"opera\") is typically a collaboration between a composer and a librettist and incorporates a number of the performing arts, such as acting, scenery, costume, and sometimes dance or ballet."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Opera", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Opera', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M31-CE002', 'D', ARRAY['D']::TEXT[], 'The correct quotation lists acting, scenery, costume, and dance alongside music.', '{"C": "This sentence defines opera.", "B": "This sentence describes the performance setting.", "A": "This sentence distinguishes opera from musical theatre."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M31-CI003', 'HDSAT-RW-M31-CI003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Film editing is the creative and technical part of the post-production process of filmmaking in which shots are combined into sequences that create a finished motion picture. The term is derived from the traditional process of working with film stock but now primarily uses digital technology. The film editor works with raw footage to select, process, and structure the recorded images and sound material to give film its final form. Film editing is often referred to as the "invisible art" because when it is well-practiced, the viewer can become so engaged that he or she is not aware of the editor''s work. Film editing is described as an art or skill that is unique to cinema, unlike, for example, cinematography or set design. On its most fundamental level, film editing is the art, technique and practice of assembling shots into a coherent sequence. The job of an editor is not simply to mechanically put pieces of a film together, cut off film slates or edit dialogue scenes. A film editor must creatively work with the layers of images, story, dialogue, music, pacing, and the actors'' performances to imagine and the film into a cohesive whole. Editors usually play a dynamic role in the making of a film. An editor must select only the most quality shots, removing unnecessary frames to ensure the shot is clean. Sometimes, auteurist film directors edit their own films, for example, Akira Kurosawa, Bahram Beyzai, Steven Soderbergh, and the Coen brothers.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Film editing consists only of removing film slates."}, {"id": "B", "text": "Film editing is the process of writing a screenplay."}, {"id": "C", "text": "Film editing is the creative post-production work of assembling shots into a coherent film, often called the invisible art."}, {"id": "D", "text": "Film editing is unrelated to storytelling."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Film editing", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Film_editing', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M31-CI003', 'C', ARRAY['C']::TEXT[], 'The passage defines film editing, describes the editor''s creative role, and explains the "invisible art" label.', '{"B": "The text says shots are combined into sequences that create a finished motion picture.", "A": "The text says the job is not simply mechanical cutting.", "D": "The text says editors work with story, dialogue, music, and pacing."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M31-INF003', 'HDSAT-RW-M31-INF003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Film editing is the creative and technical part of the post-production process of filmmaking in which shots are combined into sequences that create a finished motion picture. The term is derived from the traditional process of working with film stock but now primarily uses digital technology. The film editor works with raw footage to select, process, and structure the recorded images and sound material to give film its final form. Film editing is often referred to as the "invisible art" because when it is well-practiced, the viewer can become so engaged that he or she is not aware of the editor''s work. Film editing is described as an art or skill that is unique to cinema, unlike, for example, cinematography or set design. On its most fundamental level, film editing is the art, technique and practice of assembling shots into a coherent sequence. The job of an editor is not simply to mechanically put pieces of a film together, cut off film slates or edit dialogue scenes. A film editor must creatively work with the layers of images, story, dialogue, music, pacing, and the actors'' performances to imagine and the film into a cohesive whole. Editors usually play a dynamic role in the making of a film. An editor must select only the most quality shots, removing unnecessary frames to ensure the shot is clean. Sometimes, auteurist film directors edit their own films, for example, Akira Kurosawa, Bahram Beyzai, Steven Soderbergh, and the Coen brothers.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M31-INF003', 'A', ARRAY['A']::TEXT[], 'Invisible editing engages viewers without calling attention to the cuts.', '{"C": "The text says viewers can become so engaged they are not aware of the editor''s work.", "B": "The label implies the opposite of distraction.", "D": "The text calls editing an art or skill unique to cinema."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M31-TS003', 'HDSAT-RW-M31-TS003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Film editing is the creative and technical part of the post-production process of filmmaking in which shots are combined into sequences that create a finished motion picture. The term is derived from the traditional process of working with film stock but now primarily uses digital technology. The film editor works with raw footage to select, process, and structure the recorded images and sound material to give film its final form. Film editing is often referred to as the "invisible art" because when it is well-practiced, the viewer can become so engaged that he or she is not aware of the editor''s work. Film editing is described as an art or skill that is unique to cinema, unlike, for example, cinematography or set design. On its most fundamental level, film editing is the art, technique and practice of assembling shots into a coherent sequence. The job of an editor is not simply to mechanically put pieces of a film together, cut off film slates or edit dialogue scenes. A film editor must creatively work with the layers of images, story, dialogue, music, pacing, and the actors'' performances to imagine and the film into a cohesive whole. Editors usually play a dynamic role in the making of a film. An editor must select only the most quality shots, removing unnecessary frames to ensure the shot is clean. Sometimes, auteurist film directors edit their own films, for example, Akira Kurosawa, Bahram Beyzai, Steven Soderbergh, and the Coen brothers.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It narrates the production of a single film."}, {"id": "B", "text": "It argues that editing is purely mechanical."}, {"id": "C", "text": "It compares film editing with photography."}, {"id": "D", "text": "It defines film editing, explains the editor''s creative work, and notes directors who edit their own films."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Film editing", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Film_editing', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M31-TS003', 'D', ARRAY['D']::TEXT[], 'The passage moves from definition and role to examples of director-editors.', '{"A": "No single film is narrated.", "C": "Photography is not compared.", "B": "The text explicitly says the job is not simply mechanical."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M31-CE003', 'HDSAT-RW-M31-CE003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Film editing is the creative and technical part of the post-production process of filmmaking in which shots are combined into sequences that create a finished motion picture. The term is derived from the traditional process of working with film stock but now primarily uses digital technology. The film editor works with raw footage to select, process, and structure the recorded images and sound material to give film its final form. Film editing is often referred to as the "invisible art" because when it is well-practiced, the viewer can become so engaged that he or she is not aware of the editor''s work. Film editing is described as an art or skill that is unique to cinema, unlike, for example, cinematography or set design. On its most fundamental level, film editing is the art, technique and practice of assembling shots into a coherent sequence. The job of an editor is not simply to mechanically put pieces of a film together, cut off film slates or edit dialogue scenes. A film editor must creatively work with the layers of images, story, dialogue, music, pacing, and the actors'' performances to imagine and the film into a cohesive whole. Editors usually play a dynamic role in the making of a film. An editor must select only the most quality shots, removing unnecessary frames to ensure the shot is clean. Sometimes, auteurist film directors edit their own films, for example, Akira Kurosawa, Bahram Beyzai, Steven Soderbergh, and the Coen brothers.', 'Which quotation from the text most directly supports the claim that editing is creative rather than mechanical?', '[{"id": "A", "text": "On its most fundamental level, film editing is the art, technique and practice of assembling shots into a coherent sequence."}, {"id": "B", "text": "Film editing is the creative and technical part of the post-production process of filmmaking."}, {"id": "C", "text": "Sometimes, auteurist film directors edit their own films."}, {"id": "D", "text": "A film editor must creatively work with the layers of images, story, dialogue, music, pacing, and the actors'' performances to imagine and the film into a cohesive whole."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Film editing", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Film_editing', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M31-CE003', 'D', ARRAY['D']::TEXT[], 'The correct quotation lists the layers an editor creatively combines.', '{"B": "This sentence defines editing''s place in production.", "A": "This sentence describes the fundamental level of editing.", "C": "This sentence notes directors who edit their own work."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M31-CI004', 'HDSAT-RW-M31-CI004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Photography is the art, application, and practice of creating images by recording light, either electronically by means of an image sensor, or chemically by means of a light-sensitive material such as photographic film. It is employed in many fields of science, manufacturing (e.g., photolithography), and business, as well as its more direct uses for art, film and video production, recreational purposes, hobby, and mass communication. A person who operates a camera to capture or take photographs is called a photographer, while the captured image, also known as a photograph, is the result produced by the camera. Typically, a lens is used to focus the light reflected or emitted from objects into a real image on the light-sensitive surface inside a camera during a timed exposure. With an electronic image sensor, this produces an electrical charge at each pixel, which is electronically processed and stored in a digital image file for subsequent display or processing. The result with photographic emulsion is an invisible latent image, which is later chemically developed into a visible image, either negative or positive, depending on the purpose of the photographic material and the method of processing. A negative image on film is traditionally used to photographically create a positive image on a paper base, known as a print, either by using an enlarger or by contact printing.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Photography records light to create images, using either electronic sensors or chemical film, and serves many practical and artistic fields."}, {"id": "B", "text": "Photography records sound rather than light."}, {"id": "C", "text": "Photography is limited to scientific use."}, {"id": "D", "text": "Photography uses only chemical film today."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Photography", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Photography', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M31-CI004', 'A', ARRAY['A']::TEXT[], 'The passage defines photography, explains electronic and chemical processes, and describes its uses.', '{"B": "The text defines photography as recording light.", "D": "The text describes electronic image sensors as well as film.", "C": "The text lists art, business, science, and mass communication among its uses."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M31-INF004', 'HDSAT-RW-M31-INF004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Photography is the art, application, and practice of creating images by recording light, either electronically by means of an image sensor, or chemically by means of a light-sensitive material such as photographic film. It is employed in many fields of science, manufacturing (e.g., photolithography), and business, as well as its more direct uses for art, film and video production, recreational purposes, hobby, and mass communication. A person who operates a camera to capture or take photographs is called a photographer, while the captured image, also known as a photograph, is the result produced by the camera. Typically, a lens is used to focus the light reflected or emitted from objects into a real image on the light-sensitive surface inside a camera during a timed exposure. With an electronic image sensor, this produces an electrical charge at each pixel, which is electronically processed and stored in a digital image file for subsequent display or processing. The result with photographic emulsion is an invisible latent image, which is later chemically developed into a visible image, either negative or positive, depending on the purpose of the photographic material and the method of processing. A negative image on film is traditionally used to photographically create a positive image on a paper base, known as a print, either by using an enlarger or by contact printing.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M31-INF004', 'D', ARRAY['D']::TEXT[], 'Developing turns the invisible latent image into a visible one.', '{"A": "The text says the latent image is later chemically developed into a visible image.", "B": "Development reveals rather than erases the image.", "C": "Photography produces images, not sound."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
