xt?', '[{"id": "A", "text": "It argues that radio has disappeared."}, {"id": "B", "text": "It defines radio broadcasting, describes transmission technologies, and traces pre-radio and early broadcasting history."}, {"id": "C", "text": "It profiles a single radio host."}, {"id": "D", "text": "It compares radio with television in detail."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Radio broadcasting", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Radio_broadcasting', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
