INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M31-CE005', 'HDSAT-RW-M31-CE005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Radio broadcasting is the transmission of signals, especially audio, to receivers using radio waves over a wide area. Listeners require a broadcast radio receiver to receive these signals. "Terrestrial" broadcasts come from stations on land, and include AM and FM (both analog); and DAB (digital). Audio is also broadcast via satellite in both digital and analog, originating from a satellite in orbit around Earth. Radio stations may produce their own programming or be affiliated with a radio network that provides content either through broadcast syndication or by simulcasting, or both. The most common transmission technologies are analog and digital. Analog radio uses one of two modulation methods: amplitude modulation (AM) or frequency modulation (FM). Digital radio stations transmit using one of several digital audio standards, such as DAB (Digital Audio Broadcasting), HD Radio, or DRM (Digital Radio Mondiale). == History == === Pre-radio === Electronic distribution originated, to a limited extent, with the invention of the telegraph. The most common example, "tickers", were primarily used to distribute stock price information. An additional subscription service was time signals. The concept of audio broadcasting was first developed after the invention of telephone. In a few locations, most commonly in Europe, telephone newspapers were established, to provide news and entertainment to subscribers. These systems had the advantage of being able to charge individual customers.', 'Which quotation from the text most directly supports the claim that radio uses both analog and digital technologies?', '[{"id": "A", "text": "Listeners require a broadcast radio receiver to receive these signals."}, {"id": "B", "text": "\"Terrestrial\" broadcasts come from stations on land, and include AM and FM (both analog); and DAB (digital)."}, {"id": "C", "text": "The most common transmission technologies are analog and digital."}, {"id": "D", "text": "Radio broadcasting is the transmission of signals, especially audio, to receivers using radio waves over a wide area."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Radio broadcasting", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Radio_broadcasting', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M31-CE005', 'C', ARRAY['C']::TEXT[], 'The correct quotation states that analog and digital are the most common technologies.', '{"D": "This sentence defines broadcasting.", "A": "This sentence describes receivers.", "B": "This sentence describes terrestrial broadcast types."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M31-CI006', 'HDSAT-RW-M31-CI006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Animation is a filmmaking technique whereby pictures are created or manipulated and then played in sequence to create the illusion of moving images. In traditional animation, images are drawn or painted by hand on transparent celluloid sheets to be photographed and exhibited on film. Animation has been recognised as an artistic medium, specifically within the entertainment industry. Many animations are either traditional animations or computer animations made with computer-generated imagery (CGI). Stop motion animation, in particular claymation, is also prominent alongside these other forms, albeit to a lesser degree. Animation is contrasted with live action, although the two do not exist in isolation. Many filmmakers have produced films that are a hybrid of the two. As CGI increasingly approximates photographic imagery, filmmakers can relatively easily composite 3D animated visual effects (VFX) into their film, rather than using practical effects. == General overview == Computer animation can be very detailed 3D animation, while 2D computer animation (which may have the look of traditional animation) can be used for stylistic reasons, low bandwidth, or faster real-time renderings. Other common animation methods apply a stop motion technique to two- and three-dimensional objects like paper cutouts, puppets, or clay figures. An animated cartoon, or simply a cartoon, is an animated film, usually a short film, that features an exaggerated style.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Animation creates the illusion of movement by playing images in sequence, using traditional, computer, or stop-motion methods."}, {"id": "B", "text": "Animation is a live-action filming technique."}, {"id": "C", "text": "Animation requires no sequence of images."}, {"id": "D", "text": "Animation is limited to hand-drawn cartoons."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Animation", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Animation', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
