INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M31-CI008', 'HDSAT-RW-M31-CI008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A record label or record company is a brand or trademark of music recordings and music videos, or the company that owns it. A record label can also be a publishing company that manages such brands and trademarks, coordinates the production, manufacture, distribution, marketing, promotion, and enforcement of copyright for sound recordings and music videos, while also conducting talent scouting and development of new artists, artist financing and maintaining contracts with recording artists and their managers. The term "record label" derives from the circular label in the center of a vinyl record which prominently displays the manufacturer''s name, along with other information. Within the mainstream music industry, recording artists have traditionally been reliant upon record labels to broaden their consumer base, market their albums, and promote their singles on streaming services, radio, and television. Record labels also provide publicists, who assist performers in gaining positive media coverage, and arrange for their merchandise to be available via stores and other media outlets. == Major versus independent record labels == Record labels may be small, localized and "independent" ("indie"), or they may be part of a large international media group, or somewhere in between.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "A record label is a type of musical instrument."}, {"id": "B", "text": "A record label is a brand or company that produces, distributes, markets, and promotes recordings and develops artists."}, {"id": "C", "text": "Record labels have no role in marketing."}, {"id": "D", "text": "All record labels are large international media groups."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Record label", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Record_label', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
