INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M31-CI009', 'HDSAT-RW-M31-CI009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A documentary film (often called simply a documentary) is a nonfiction motion picture intended to "document reality, primarily for instruction, education or maintaining a historical record". Research into information gathering, as a behavior, and the sharing of knowledge, as a concept, has noted how documentary movies were preceded by the notable practice of documentary photography. This has involved the use of singular photographs to detail the complex attributes of historical events and continues to a certain degree to this day, with an example being the conflict-related photography achieved by popular figures such as Mathew Brady during the American Civil War. Documentary movies evolved from the creation of singular images in order to convey particular types of information in depth, using film as a medium. Early documentary films, originally called "actuality films", briefly lasted for one minute or less in most cases. While faithfully depicting true events, these releases possessed no narrative structure per se and were of limited interest. Over time, documentaries have evolved to become longer in length and to include more categories of information. Some examples are explicitly educational, while others serve as observational works; docufiction movies notably include aspects of dramatic storytelling that are clearly fictional. Documentaries are informative at times, and certain types are often used within schools as a resource to teach various principles.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Documentaries are fictional narrative films."}, {"id": "B", "text": "Documentaries are used only for entertainment."}, {"id": "C", "text": "Documentary films are nonfiction works that record reality for instruction or history, evolving from short actuality films into varied forms."}, {"id": "D", "text": "Documentaries have never changed since their invention."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Documentary film", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Documentary_film', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M31-CI009', 'C', ARRAY['C']::TEXT[], 'The passage defines documentary film, traces its evolution, and describes its varied types.', '{"A": "The text defines documentaries as nonfiction motion pictures.", "D": "The text says they evolved to become longer and include more categories.", "B": "The text says some are explicitly educational and some are used in schools."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M31-INF009', 'HDSAT-RW-M31-INF009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A documentary film (often called simply a documentary) is a nonfiction motion picture intended to "document reality, primarily for instruction, education or maintaining a historical record". Research into information gathering, as a behavior, and the sharing of knowledge, as a concept, has noted how documentary movies were preceded by the notable practice of documentary photography. This has involved the use of singular photographs to detail the complex attributes of historical events and continues to a certain degree to this day, with an example being the conflict-related photography achieved by popular figures such as Mathew Brady during the American Civil War. Documentary movies evolved from the creation of singular images in order to convey particular types of information in depth, using film as a medium. Early documentary films, originally called "actuality films", briefly lasted for one minute or less in most cases. While faithfully depicting true events, these releases possessed no narrative structure per se and were of limited interest. Over time, documentaries have evolved to become longer in length and to include more categories of information. Some examples are explicitly educational, while others serve as observational works; docufiction movies notably include aspects of dramatic storytelling that are clearly fictional. Documentaries are informative at times, and certain types are often used within schools as a resource to teach various principles.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M31-INF009', 'B', ARRAY['B']::TEXT[], 'Short, unstructured actuality films were described as of limited interest.', '{"A": "The text says they were of limited interest.", "C": "The text says they briefly lasted a minute or less.", "D": "The text says they possessed no narrative structure."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M31-TS009', 'HDSAT-RW-M31-TS009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A documentary film (often called simply a documentary) is a nonfiction motion picture intended to "document reality, primarily for instruction, education or maintaining a historical record". Research into information gathering, as a behavior, and the sharing of knowledge, as a concept, has noted how documentary movies were preceded by the notable practice of documentary photography. This has involved the use of singular photographs to detail the complex attributes of historical events and continues to a certain degree to this day, with an example being the conflict-related photography achieved by popular figures such as Mathew Brady during the American Civil War. Documentary movies evolved from the creation of singular images in order to convey particular types of information in depth, using film as a medium. Early documentary films, originally called "actuality films", briefly lasted for one minute or less in most cases. While faithfully depicting true events, these releases possessed no narrative structure per se and were of limited interest. Over time, documentaries have evolved to become longer in length and to include more categories of information. Some examples are explicitly educational, while others serve as observational works; docufiction movies notably include aspects of dramatic storytelling that are clearly fictional. Documentaries are informative at times, and certain types are often used within schools as a resource to teach various principles.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares documentaries with music videos."}, {"id": "B", "text": "It argues that documentaries are always objective."}, {"id": "C", "text": "It reviews a single documentary in detail."}, {"id": "D", "text": "It defines documentary film, traces its evolution from photography and actuality films, and describes its types."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Documentary film", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Documentary_film', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
