im that music theory has more than one meaning?', '[{"id": "A", "text": "This medieval discipline became the basis for tuning systems in later centuries."}, {"id": "B", "text": "The Oxford Companion to Music describes three interrelated uses of the term \"music theory\": The first refers to the \"rudiments\" needed to understand music notation such as key signatures, time signatures, and rhythmic notation; the second is a study of scholars'' views on music from antiquity to the present; the third is a sub-topic of musicology that \"seeks to define processes and general principles in music\"."}, {"id": "C", "text": "Music theory is frequently concerned with describing how musicians and composers make music."}, {"id": "D", "text": "Music theory is the study of theoretical frameworks for understanding the practices and possibilities of music."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Music theory", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Music_theory', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
